1	package indexroom
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"reflect"
10		"strings"
11		"sync"
12		"testing"
13	)
14	
15	func exportString(t *testing.T, index *Index) string {
16		t.Helper()
17		var buf bytes.Buffer
18		if err := index.Export(&buf); err != nil {
19			t.Fatalf("export failed: %v", err)
20		}
21		return buf.String()
22	}
23	
24	// genericSnapshot is a schema-free view of exported bytes for invariant
25	// checks that should not depend on the production struct tags.
26	type genericSnapshot struct {
27		Version int64 `json:"version"`
28		Tip     int64 `json:"tip"`
29		Blocks  []struct {
30			Height int64    `json:"height"`
31			Hash   string   `json:"hash"`
32			Parent string   `json:"parent"`
33			Txs    []string `json:"txs"`
34		} `json:"blocks"`
35	}
36	
37	// requireWellFormedSnapshot checks the exported bytes describe one complete
38	// contiguous chain. It reports rather than fails fatally so it is safe to
39	// call from helper goroutines.
40	func requireWellFormedSnapshot(t *testing.T, raw string) {
41		t.Helper()
42		var doc genericSnapshot
43		if err := json.Unmarshal([]byte(raw), &doc); err != nil {
44			t.Errorf("exported snapshot does not parse: %v", err)
45			return
46		}
47		if doc.Version != 1 {
48			t.Errorf("exported version=%d, want 1", doc.Version)
49		}
50		for i, block := range doc.Blocks {
51			if want := int64(i + 1); block.Height != want {
52				t.Errorf("exported block %d has height %d, want %d", i, block.Height, want)
53				return
54			}
55			if i > 0 && block.Parent != doc.Blocks[i-1].Hash {
56				t.Errorf("exported block at height %d breaks the parent link", block.Height)
57				return
58			}
59		}
60		last := int64(0)
61		if len(doc.Blocks) > 0 {
62			last = doc.Blocks[len(doc.Blocks)-1].Height
63		}
64		if doc.Tip != last {
65			t.Errorf("exported tip=%d, last height=%d", doc.Tip, last)
66		}
67	}
68	
69	func TestExportEmptyIndex(t *testing.T) {
70		raw := exportString(t, New())
71		if raw != `{"version":1,"tip":0,"blocks":[]}` {
72			t.Fatalf("empty export=%s", raw)
73		}
74	}
75	
76	func TestExportExactBytes(t *testing.T) {
77		index := chain(t,
78			Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"t1", "t2"}},
79			Block{Height: 2, Hash: "h2", Parent: "h1"},
80		)
81		want := `{"version":1,"tip":2,"blocks":[` +
82			`{"height":1,"hash":"h1","parent":"genesis","txs":["t1","t2"]},` +
83			`{"height":2,"hash":"h2","parent":"h1","txs":[]}` +
84			`]}`
85		if raw := exportString(t, index); raw != want {
86			t.Fatalf("export=%s\nwant=%s", raw, want)
87		}
88	}
89	
90	func TestExportDeterministicAcrossHistory(t *testing.T) {
91		// indexA reaches h1,h2b,h3b through a reorg; indexB appends it directly.
92		indexA := chain(t,
93			Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"t1"}},
94			Block{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"gone"}},
95			Block{Height: 3, Hash: "h3", Parent: "h2"},
96		)
97		if _, err := indexA.Reorg([]Block{
98			{Height: 2, Hash: "h2b", Parent: "h1", Txs: []string{"t2"}},
99			{Height: 3, Hash: "h3b", Parent: "h2b"},
100		}); err != nil {
101			t.Fatal(err)
102		}
103		indexB := chain(t,
104			Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"t1"}},
105			Block{Height: 2, Hash: "h2b", Parent: "h1", Txs: []string{"t2"}},
106			Block{Height: 3, Hash: "h3b", Parent: "h2b"},
107		)
108		rawA, rawB := exportString(t, indexA), exportString(t, indexB)
109		if rawA != rawB {
110			t.Fatalf("same main chain exported different bytes:\n%s\n%s", rawA, rawB)
