590			if err := index.Restore(strings.NewReader(raw)); err != nil {
591				t.Fatal(err)
592			}
593			page, err := index.QueryTxs(TxQuery{PageSize: 1, Cursor: cursor})
594			if err != nil {
595				t.Fatalf("continuation after identical restore failed: %v", err)
596			}
597			want := []TxHit{{Height: 2, BlockHash: "h2", TxID: "b", Position: 0}}
598			if !reflect.DeepEqual(page.Hits, want) {
599				t.Fatalf("hits=%v, want %v", page.Hits, want)
600			}
601		})
602	
603		t.Run("changed range kills the cursor", func(t *testing.T) {
604			index, cursor := build(t)
605			snap := `{"version":1,"tip":3,"blocks":[` +
606				`{"height":1,"hash":"h1","parent":"genesis","txs":["a"]},` +
607				`{"height":2,"hash":"h2","parent":"h1","txs":["CHANGED"]},` +
608				`{"height":3,"hash":"h3","parent":"h2","txs":["c"]}` +
609				`]}`
610			if err := index.Restore(strings.NewReader(snap)); err != nil {
611				t.Fatal(err)
612			}
613			if _, err := index.QueryTxs(TxQuery{PageSize: 1, Cursor: cursor}); !errors.Is(err, ErrQueryChanged) {
614				t.Fatalf("err=%v, want ErrQueryChanged", err)
615			}
616		})
617	
618		t.Run("shortened chain kills the cursor", func(t *testing.T) {
619			index, cursor := build(t)
620			snap := `{"version":1,"tip":1,"blocks":[` +
621				`{"height":1,"hash":"h1","parent":"genesis","txs":["a"]}` +
622				`]}`
623			if err := index.Restore(strings.NewReader(snap)); err != nil {
624				t.Fatal(err)
625			}
626			if _, err := index.QueryTxs(TxQuery{PageSize: 1, Cursor: cursor}); !errors.Is(err, ErrQueryChanged) {
627				t.Fatalf("err=%v, want ErrQueryChanged", err)
628			}
629		})
630	}
631	
632	func TestRestoreWhileStreamOpenIndexStaysUsable(t *testing.T) {
633		index := txChain(t, []string{"a"}, []string{"b"})
634		pr, pw := io.Pipe()
635		done := make(chan error, 1)
636		go func() {
637			done <- index.Restore(pr)
638		}()
639		// Deliver only a prefix; the restore is now blocked mid-stream.
640		if _, err := pw.Write([]byte(`{"version":1,"tip":0,`)); err != nil {
641			t.Fatal(err)
642		}
643		// The index stays queryable and appendable while the stream is open.
644		page, err := index.QueryTxs(TxQuery{})
645		if err != nil || page.TotalMatches != 2 {
646			t.Fatalf("query while restore in flight: page=%+v err=%v", page, err)
647		}
648		if err := index.Append(Block{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"c"}}); err != nil {
649			t.Fatalf("append while restore in flight: %v", err)
650		}
651		// Ending the stream early fails the restore without touching the chain.
652		if err := pw.Close(); err != nil {
653			t.Fatal(err)
654		}
655		if err := <-done; !errors.Is(err, ErrInvalidSnapshot) {
656			t.Fatalf("restore err=%v, want ErrInvalidSnapshot", err)
657		}
658		// Only the append changed the chain; the failed restore left no trace.
659		if index.Tip != 3 || len(index.Blocks) != 3 || index.Blocks[3].Hash != "h3" {
660			t.Fatalf("unexpected state: tip=%d blocks=%v", index.Tip, index.Blocks)
661		}
662	}
663	
664	func TestSnapshotConcurrentWithChainOps(t *testing.T) {
665		source := txChain(t, []string{"seed"})
666		var wg sync.WaitGroup
667	
668		// One writer keeps appending; exporters must always observe one complete
669		// contiguous chain.
670		stop := make(chan struct{})
671		var writer sync.WaitGroup
672		writer.Add(1)
673		go func() {
674			defer writer.Done()
675			for height := int64(2); height <= 300; height++ {
676				select {
677				case <-stop:
678					return
679				default:
680				}
681				block := Block{
682					Height: height,
683					Hash:   fmt.Sprintf("h%d", height),
684					Parent: fmt.Sprintf("h%d", height-1),
685					Txs:    []string{fmt.Sprintf("tx-%d", height)},
686				}
687				if err := source.Append(block); err != nil {
688					return
689				}
690			}
691		}()
692	
693		for exporter := 0; exporter < 3; exporter++ {
694			wg.Add(1)
695			go func() {
696				defer wg.Done()
697				for round := 0; round < 30; round++ {
698					var buf bytes.Buffer
699					if err := source.Export(&buf); err != nil {
700						t.Errorf("export failed: %v", err)
701						return
702					}
703					requireWellFormedSnapshot(t, buf.String())
704				}
705			}()
706		}
707	
708		// Restores and queries race on a second index; every restore applies a
709		// complete snapshot, so queries always see a contiguous chain.
710		target := New()
711		raw := exportString(t, txChain(t,
712			[]string{"a", "b"},
713			[]string{"c"},
714			[]string{"d"},
715		))
716		for worker := 0; worker < 2; worker++ {
717			wg.Add(1)
718			go func() {
719				defer wg.Done()
720				for round := 0; round < 20; round++ {
721					if err := target.Restore(strings.NewReader(raw)); err != nil {
722						t.Errorf("restore failed: %v", err)
723						return
724					}
725				}
726			}()
727		}
728		for reader := 0; reader < 2; reader++ {
729			wg.Add(1)
730			go func() {
731				defer wg.Done()
732				for round := 0; round < 40; round++ {
733					page, err := target.QueryTxs(TxQuery{})
734					if err != nil {
735						t.Errorf("query failed: %v", err)
736						return
737					}
738					lastHeight, lastPosition := int64(0), -1
739					for _, hit := range page.Hits {
740						if hit.Height < lastHeight || (hit.Height == lastHeight && hit.Position <= lastPosition) {
741							t.Errorf("hits out of order: %+v after (%d,%d)", hit, lastHeight, lastPosition)
742							return
743						}
744						lastHeight, lastPosition = hit.Height, hit.Position
745					}
746				}
747			}()
748		}
749	
750		wg.Wait()
751		close(stop)
752		writer.Wait()
753	}
