1	package indexroom
2	
3	import (
4		"errors"
5		"reflect"
6		"strings"
7		"testing"
8	)
9	
10	func TestExportV2ExactBytes(t *testing.T) {
11		index := New()
12		blocks := []Block{
13			{Height: 1, Hash: "h1", Parent: "g", Txs: []string{"t1"}, Time: nil},
14			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{}, Time: intptr(0)},
15			{Height: 3, Hash: "h3", Parent: "h2", Time: intptr(1700000000)},
16		}
17		for _, b := range blocks {
18			if err := index.Append(b); err != nil {
19				t.Fatal(err)
20			}
21		}
22		want := `{"version":2,"tip":3,"blocks":[` +
23			`{"height":1,"hash":"h1","parent":"g","txs":["t1"],"timestamp":null},` +
24			`{"height":2,"hash":"h2","parent":"h1","txs":[],"timestamp":0},` +
25			`{"height":3,"hash":"h3","parent":"h2","txs":[],"timestamp":1700000000}` +
26			`]}`
27		if raw := exportString(t, index); raw != want {
28			t.Fatalf("export=%s\nwant=%s", raw, want)
29		}
30	}
31	
32	func TestExportStaysV1WhenAllTimesMissing(t *testing.T) {
33		// Chains restored from version 1 and chains appended without times both
34		// export the original version-1 bytes, including the empty index.
35		index := chain(t,
36			Block{Height: 1, Hash: "h1", Parent: "g", Txs: []string{"t1"}},
37			Block{Height: 2, Hash: "h2", Parent: "h1"},
38		)
39		want := `{"version":1,"tip":2,"blocks":[` +
40			`{"height":1,"hash":"h1","parent":"g","txs":["t1"]},` +
41			`{"height":2,"hash":"h2","parent":"h1","txs":[]}` +
42			`]}`
43		if raw := exportString(t, index); raw != want {
44			t.Fatalf("export=%s\nwant=%s", raw, want)
45		}
46	
47		v1 := `{"version":1,"tip":1,"blocks":[{"height":1,"hash":"h1","parent":"g","txs":[]}]}`
48		restored := New()
49		if err := restored.Restore(strings.NewReader(v1)); err != nil {
50			t.Fatal(err)
51		}
52		if raw := exportString(t, restored); raw != v1 {
53			t.Fatalf("restored v1 re-exported as %s", raw)
54		}
55	}
56	
57	func TestRestoreV1TreatsTimestampsAsMissing(t *testing.T) {
58		v1 := `{"version":1,"tip":2,"blocks":[` +
59			`{"height":1,"hash":"h1","parent":"g","txs":["a"]},` +
60			`{"height":2,"hash":"h2","parent":"h1","txs":["b"]}` +
61			`]}`
62		index := New()
63		if err := index.Restore(strings.NewReader(v1)); err != nil {
64			t.Fatal(err)
