func TestQueryTxsRejectsInvalidArguments(t *testing.T) {
	index := txChain(t, []string{"a"}, []string{"b"})
	for name, query := range map[string]TxQuery{
		"negative from":  {From: -1},
		"negative to":    {To: -2},
