116	func TestRestoreAcceptsValidUnicodeIdentifiers(t *testing.T) {
117		// The same character written literally and as escapes must decode to
118		// the same identifier: the escaped emoji in txs[0] equals the literal
119		// one in txs[4], the escaped 中文 parent links to the literal hash, and
120		// a genuine U+FFFD — literal or escaped — is valid input.
121		input := v1Chain(
122			`{"height":1,"hash":"中文","parent":"中文","txs":["tx-`+esc("d83d")+esc("de00")+`","�","`+esc("fffd")+`","","tx-😀"]}`,
123			`{"height":2,"hash":"`+esc("d83d")+esc("de00")+`","parent":"`+esc("4e2d")+esc("6587")+`","txs":["h\\u0041sh"]}`,
124		)
