173	// dripReader delivers its data one byte at a time, so a multi-byte UTF-8
174	// character is split across several Read calls.
175	type dripReader struct{ data []byte }
176	
177	func (r *dripReader) Read(p []byte) (int, error) {
178		if len(r.data) == 0 {
179			return 0, io.EOF
180		}
181		p[0] = r.data[0]
