func (l *liveReReader) Write(p []byte) (int, error) {
	// Wait (without holding the lock) until a reorg replaced height 2: this
	// models a faulty implementation that serializes live state while the
	// sink is still receiving, instead of pinning a copy taken under lock.
	for {
		l.index.mu.Lock()
		reorged := strings.HasPrefix(l.index.Blocks[2].Hash, "new-")
		l.index.mu.Unlock()
		if reorged {
			break
		}
		time.Sleep(time.Millisecond)
	}
	l.index.mu.Lock()

