1	package indexroom
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"io"
8		"reflect"
9		"strings"
10		"testing"
11	)
12	
13	// These tests pin down the observable contract that one Export observes one
14	// complete main-chain state: once serialization has started, a reorg that
15	// replaces the branch while the output sink has not yet received the whole
16	// document neither blocks nor contaminates the in-flight snapshot, and a
17	// completed reorg is never undone by an output failure discovered afterwards.
18	
19	// assertExportStillRunning fails if the export goroutine has already
20	// returned. It is a non-blocking observation point that distinguishes the
21	// "export not finished yet" state from the "reorg completed" state without
22	// any sleeps.
23	func assertExportStillRunning(t *testing.T, done <-chan error) {
24		t.Helper()
25		select {
26		case err := <-done:
27			t.Fatalf("export finished before the sink was released: %v", err)
28		default:
29		}
30	}
31	
32	func TestExportPinsCompleteChainStateAcrossMidStreamReorg(t *testing.T) {
33		// The old main chain mixes every timestamp shape: a missing time, a
34		// real zero timestamp, and the only non-zero timestamp. Its duplicate
35		// identifiers, empty identifier, and their ordering must all survive.
36		index := chain(t,
37			Block{Height: 1, Hash: "old-a", Parent: "genesis", Txs: []string{"dup", ""}},
38			Block{Height: 2, Hash: "old-b", Parent: "old-a", Txs: []string{"dup", "old-tx"}, Time: intptr(0)},
39			Block{Height: 3, Hash: "old-c", Parent: "old-b", Txs: []string{"old-tx", "after"}, Time: intptr(1700000000)},
40		)
41		wantOldSnapshot := `{"version":2,"tip":3,"blocks":[` +
42			`{"height":1,"hash":"old-a","parent":"genesis","txs":["dup",""],"timestamp":null},` +
43			`{"height":2,"hash":"old-b","parent":"old-a","txs":["dup","old-tx"],"timestamp":0},` +
44			`{"height":3,"hash":"old-c","parent":"old-b","txs":["old-tx","after"],"timestamp":1700000000}` +
45			`]}`
46	
47		// A pipe lets the test hold the export mid-write: Export makes one Write
48		// of the whole document, which stays blocked until every byte is drained.
49		// Closing the pipe after Export returns gives the drainer its EOF.
50		pr, pw := io.Pipe()
51		done := make(chan error, 1)
52		go func() {
53			err := index.Export(pw)
54			pw.Close()
55			done <- err
56		}()
57	
58		// Observable state 1: writing has begun (one byte already in flight) but
59		// the export has not finished.
60		first := make([]byte, 1)
61		if n, err := pr.Read(first); err != nil || n != 1 {
62			t.Fatalf("first read: n=%d err=%v", n, err)
63		}
64		if string(first[0]) != wantOldSnapshot[:1] {
65			t.Fatalf("in-flight output starts with %q, want %q", first[0], wantOldSnapshot[0])
66		}
67		assertExportStillRunning(t, done)
68	
69		// While that write is still open, a legal reorg replaces heights 2 and 3
70		// and extends the chain with a new block. The replacement branch carries
71		// no timestamps at all.
72		dropped, err := index.Reorg([]Block{
73			{Height: 2, Hash: "new-b", Parent: "old-a", Txs: []string{"new-tx", "", "new-tx"}},
74			{Height: 3, Hash: "new-c", Parent: "new-b", Txs: []string{"after"}},
75			{Height: 4, Hash: "new-d", Parent: "new-c", Txs: []string{"new-tx"}},
76		})
77		if err != nil {
78			t.Fatalf("reorg while export in flight refused: %v", err)
79		}
80		if !reflect.DeepEqual(dropped, []int64{2, 3}) {
81			t.Fatalf("dropped=%v, want [2 3]", dropped)
82		}
83	
84		// Observable state 2: the reorg has completed and is visible through
85		// queries and the index, while the earlier export is still open.
86		assertExportStillRunning(t, done)
87		if index.Tip != 4 || index.Blocks[2].Hash != "new-b" || index.Blocks[3].Hash != "new-c" {
88			t.Fatalf("reorg not observable on the index: %+v", index.Blocks)
89		}
90		for _, gone := range []string{"old-b", "old-c"} {
91			if _, ok := index.ByHash[gone]; ok {
92				t.Fatalf("reorged-away hash %s still indexed", gone)
93			}
94		}
95		if got := index.Blocks[2].Txs; !reflect.DeepEqual(got, []string{"new-tx", "", "new-tx"}) {
96			t.Fatalf("new block txs=%q", got)
97		}
98		page, err := index.QueryTxs(TxQuery{})
99		if err != nil || page.TotalMatches != 7 || page.ToHeight != 4 {
100			t.Fatalf("query after reorg: page=%+v err=%v", page, err)
101		}
102		page, err = index.QueryTxs(TxQuery{TxIDs: []string{"old-tx"}})
103		if err != nil || page.TotalMatches != 0 {
104			t.Fatalf("old tx still queryable after reorg: %+v err=%v", page, err)
105		}
106		page, err = index.QueryTxs(TxQuery{TxIDs: []string{"new-tx"}})
107		if err != nil {
108			t.Fatal(err)
109		}
110		wantNewHits := []TxHit{
111			{Height: 2, BlockHash: "new-b", TxID: "new-tx", Position: 0},
112			{Height: 2, BlockHash: "new-b", TxID: "new-tx", Position: 2},
113			{Height: 4, BlockHash: "new-d", TxID: "new-tx", Position: 0},
114		}
115		if !reflect.DeepEqual(page.Hits, wantNewHits) {
116			t.Fatalf("new-tx hits=%v, want %v", page.Hits, wantNewHits)
117		}
118	
119		// The sink finishes receiving: the export ends successfully and its
120		// bytes describe exactly the old main chain selected when writing began.
121		rest, err := io.ReadAll(pr)
122		if err != nil {
123			t.Fatalf("draining the export failed: %v", err)
124		}
125		if err := <-done; err != nil {
126			t.Fatalf("export after reorg failed: %v", err)
127		}
128		raw := string(first[0]) + string(rest)
129		if raw != wantOldSnapshot {
130			t.Fatalf("pinned export=%s\nwant=%s", raw, wantOldSnapshot)
131		}
132		// Explicit leakage guards: the document must name no replacement hash,
133		// transaction, or the new tip, and must keep the old height cap.
134		for _, leaked := range []string{"new-b", "new-c", "new-d", "new-tx", `"tip":4`} {
135			if strings.Contains(raw, leaked) {
136				t.Fatalf("old snapshot leaks replacement content %q: %s", leaked, raw)
137			}
138		}
139		var timedDoc struct {
140			Version int64 `json:"version"`
141			Tip     int64 `json:"tip"`
142			Blocks  []struct {
143				Height    int64           `json:"height"`
144				Hash      string          `json:"hash"`
145				Parent    string          `json:"parent"`
146				Txs       []string        `json:"txs"`
147				Timestamp json.RawMessage `json:"timestamp"`
148			} `json:"blocks"`
149		}
150		if err := json.Unmarshal([]byte(raw), &timedDoc); err != nil {
151			t.Fatalf("pinned snapshot does not parse: %v", err)
152		}
153		if timedDoc.Version != 2 || timedDoc.Tip != 3 || len(timedDoc.Blocks) != 3 {
154			t.Fatalf("pinned snapshot shape: %+v", timedDoc)
155		}
156		wantTimes := []string{"null", "0", "1700000000"}
157		for i, block := range timedDoc.Blocks {
158			if got := string(block.Timestamp); got != wantTimes[i] {
159				t.Fatalf("block %d timestamp=%s, want %s", i+1, got, wantTimes[i])
160			}
161			if i > 0 && block.Parent != timedDoc.Blocks[i-1].Hash {
162				t.Fatalf("pinned snapshot breaks the parent link at height %d", block.Height)
163			}
164		}
165	
166		// The old snapshot restores into a separate index: old-chain txs are
167		// queryable there, including duplicates, the empty id, and their order;
168		// missing/zero/real timestamps come back as distinct values.
169		restored := New()
170		if err := restored.Restore(strings.NewReader(raw)); err != nil {
171			t.Fatalf("restore of pinned snapshot failed: %v", err)
172		}
173		if restored.Blocks[1].Time != nil {
174			t.Fatalf("height 1 time=%v, want missing", restored.Blocks[1].Time)
175		}
176		if restored.Blocks[2].Time == nil || *restored.Blocks[2].Time != 0 {
177			t.Fatalf("height 2 time=%v, want 0", restored.Blocks[2].Time)
178		}
179		if restored.Blocks[3].Time == nil || *restored.Blocks[3].Time != 1700000000 {
180			t.Fatalf("height 3 time=%v, want 1700000000", restored.Blocks[3].Time)
181		}
182		page, err = restored.QueryTxs(TxQuery{})
183		if err != nil || page.TotalMatches != 6 || page.ToHeight != 3 {
184			t.Fatalf("restored old-chain query: page=%+v err=%v", page, err)
185		}
186		page, err = restored.QueryTxs(TxQuery{TxIDs: []string{"old-tx"}})
187		if err != nil {
188			t.Fatal(err)
189		}
190		wantOldHits := []TxHit{
191			{Height: 2, BlockHash: "old-b", TxID: "old-tx", Position: 1},
192			{Height: 3, BlockHash: "old-c", TxID: "old-tx", Position: 0},
193		}
194		if !reflect.DeepEqual(page.Hits, wantOldHits) {
195			t.Fatalf("old-tx hits on restored index=%v, want %v", page.Hits, wantOldHits)
196		}
197		page, err = restored.QueryTxs(TxQuery{TxIDs: []string{"new-tx"}})
198		if err != nil || page.TotalMatches != 0 {
199			t.Fatalf("restored old index sees replacement txs: %+v err=%v", page, err)
200		}
201		if again := exportString(t, restored); again != raw {
202			t.Fatalf("re-export of restored old snapshot differs:\n%s\n%s", again, raw)
203		}
204	
205		// Restoring the old chain elsewhere leaves the current main chain alone.
206		page, err = index.QueryTxs(TxQuery{TxIDs: []string{"after"}})
207		if err != nil {
208			t.Fatal(err)
209		}
210		wantAfter := []TxHit{{Height: 3, BlockHash: "new-c", TxID: "after", Position: 0}}
211		if !reflect.DeepEqual(page.Hits, wantAfter) {
212			t.Fatalf("after-tx on current index=%v, want %v", page.Hits, wantAfter)
213		}
214	
215		// A second export after the reorg reflects only the new, fully untimed
216		// chain: version 1, no timestamp field anywhere, tip and hashes new.
217		wantNewSnapshot := `{"version":1,"tip":4,"blocks":[` +
218			`{"height":1,"hash":"old-a","parent":"genesis","txs":["dup",""]},` +
219			`{"height":2,"hash":"new-b","parent":"old-a","txs":["new-tx","","new-tx"]},` +
220			`{"height":3,"hash":"new-c","parent":"new-b","txs":["after"]},` +
221			`{"height":4,"hash":"new-d","parent":"new-c","txs":["new-tx"]}` +
